{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It defines an immigration officer as a state, local, or federal law enforcement officer seeking to enforce immigration law.",
      "rationale": "Conveys the full operative definition. The omitted federal agency examples do not narrow the definition or add a separate requirement."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would require a school district director or public charter school director to immediately notify all enrolled students and their parents, educators, employees, and contractors when an immigration officer is on school grounds.",
      "rationale": "Identifies the responsible directors, immediate notification requirement, all recipient groups, and the school-grounds trigger. The omitted statutory cross-references are not essential to identifying this requirement."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill says this notice requirement, and any school board or charter school governing body policy to carry it out, would not count as a sanctuary policy. It would also protect the specified school officials and employees from penalties under the cited sanctuary-policy laws for adopting or enforcing such a policy.",
      "rationale": "Conveys both the exclusion from sanctuary-policy classification and the protection against adoption or enforcement penalties. In context, school officials and employees adequately summarizes the protected board members, governing-body members, directors, and employees."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "States the effective-date provision accurately."
    }
  ]
}
